from h34 import *
M=mcq;F=tf;S=short;N=num
numberline('c3-hundreds-line.svg',200,300,10,[(200,250,'+50'),(250,280,'+30'),(280,300,'+20')],'Counting from 200 to 300 in jumps')
chapter(3,'maths','house-of-hundreds-1','House of Hundreds - I',
 ('At the mela with Teji and Jojo','Ajji, Teji and Jojo go to a mela and see hundreds of things: triangular flags on a string, heaps of bangles and boxes of toffees. Teji says there are far too many to count one by one. So they learn to count in tens and hundreds and to write the numbers beyond 100.'),
 [('Guessing and counting big collections',['Before we count a big collection, we make a guess. A guess helps us notice if the number is near 100, 200 or 300.','To count correctly, we make groups of ten. Counting ten, twenty, thirty and so on is quicker than counting one by one and we make fewer mistakes.','Two hundred triangular flags and 5 more groups of ten make 250 flags. Two hundred bangles and 8 groups of ten make 280 bangles.','When we reach 298 toffees and add one, we get 299, and one more makes 300. Three hundred is 3 hundreds, which is the same as 30 tens.']),
  ('Reading and writing numbers with bundles',['A hundred is a bundle of ten tens. We can show 235 as 2 hundreds, 3 tens and 5 ones, or as 200 and 35 more.','We can write it as a number sentence, 200 + 35 = 235. We can also write 15 less than 250 as 250 - 15 = 235.','The same number can be written in many ways. 300 and 16 more is 316, and 316 is also 300 + 10 + 6.','A number slider helps us change a number. Moving up one place adds one, moving to the tens place adds ten and moving to the hundreds place adds one hundred.']),
  ('Numbers on a number line',['On the number line from 200 to 300 the numbers are in order, and every mark is a number that is ten more than the one before.','235 lies between 200 and 250. It is 35 steps after 200 and 15 steps before 250, so it sits close to 250.','A number line also tells us how far one number is from another. 387 is 13 steps away from 400, and 393 is smaller than 400 because it comes before it.','After one hundred, two hundred and three hundred the next number name is four hundred, and then five hundred.']),
  ('Number games and house numbers',['In the flag game Teji thinks of a number between 200 and 210. Jojo guesses 205, and the flag points to the right because the secret number is larger than the guess.','Each guess cuts down the numbers left. By the third or fourth guess Jojo can find the answer, 207.','In the magical count game we write a number name, count its letters, write that new number name, and keep going. Surprisingly we always end at four.','House numbers in a tall building follow a pattern. One floor above 105 is 115, so going up adds ten, and the house to the right adds one.'])],
 [('The flags on a string are in groups: 2 hundred and 5 tens. How many flags are there?',[('2 hundreds is 200 and 5 tens is 50.','Value of each group.'),('200 + 50 = 250 flags.','Add the hundreds and the tens.'),('Check by counting 10, 20, ... 250 on the number line.','Counting by tens confirms it.')]),
  ('Write 15 less than 250.',[('Less than means take away.','Choose subtraction.'),('250 - 15: take 10 away to get 240 and then 5 more to get 235.','Break 15 into 10 and 5.'),('The number is 235.','Check by adding: 235 + 15 = 250.')]),
  ('Where is house 143 compared with house 133 in the apartment block?',[('Going up one floor adds 10.','The house numbers follow a pattern of tens.'),('133 + 10 = 143, so 143 is on the floor above 133 in the same column.','Same column, one floor higher.')])],
 ('Explain how you would count 340 bangles correctly.',['Make groups of ten','Count 10, 20, 30 and so on','Use hundreds as bigger bundles','340 is 300 and 40 more'],['Counting one by one is the best way','100 and 10 are the same size']),
 ['We count big collections in groups of ten and then hundreds.','A number like 235 is 2 hundreds, 3 tens and 5 ones, or 200 + 35.','On a number line the numbers go in order, and numbers on the right are bigger.','After 299 comes 300, after 399 comes 400.','In a building the house number goes up by ten when we go one floor up and by one when we move one house to the right.'],
 [M('1',1,'What number comes after 299?','300',[('290','290 is smaller than 299'),('301','301 comes after 300')],'299 + 1 = 300.'),
  N('2',1,'200 and 35 more makes how many?',235,'200 + 35 = 235.',[(2035,'Add 35 to 200, do not write them side by side'),(215,'Add 35, not 15')]),
  N('3',1,'What is 15 less than 250?',235,'250 - 15 = 235.',[(265,'That is 15 more'),(245,'Take away 15, not 5')]),
  M('4',1,'In 235, how many hundreds are there?','2',[('3','3 is the number of tens'),('5','5 is the number of ones')],'235 has 2 hundreds, 3 tens and 5 ones.'),
  N('5',2,'Count by tens: 280, 290, ?',300,'290 + 10 = 300.',[(295,'That jumps by five'),(310,'That is two jumps')]),
  M('6',2,'Which number is between 200 and 250?','235',[('265','265 is more than 250'),('195','195 is less than 200')],'235 is more than 200 and less than 250.'),
  N('7',2,'How far is 387 from 400?',13,'387 + 3 = 390, and 10 more makes 400, so 3 + 10 = 13.',[(23,'Count again from 387 to 400'),(3,'That only reaches 390')]),
  F('8',2,'393 is more than 400.',False,'393 comes before 400 on the number line, so it is smaller.'),
  N('9',2,'In the building, the house on the floor above 105 is numbered?',115,'One floor up adds ten: 105 + 10 = 115.',[(106,'That is the next house to the right'),(125,'That is two floors up')]),
  S('10',2,'After three hundred, what is the next hundred number name?',['four hundred','400'],'The hundreds go one hundred, two hundred, three hundred, four hundred.'),
  M('11',3,'Jojo guesses 205 and the flag points to the right. What does that tell us?','The secret number is bigger than 205',[('The secret number is smaller than 205','A flag to the right means bigger'),('205 is correct','Then there would be no flag')],'The flag points to bigger numbers on the right.'),
  N('12',3,'Count 250 + 30 = ?',280,'250 and 3 tens: 260, 270, 280.',[(253,'Add three tens, not three ones'),(550,'Add 30, not 300')])],
 svgs=[('c3-hundreds-line','A number line from 200 to 300 showing jumps of 50, 30 and 20','We can reach 300 from 200 in friendly jumps.')],
 keep=['hundred','number line','tens'])
